#include "SyncEngine.h"
#include "DatabaseManager.h"
#include "kiriflux.h" // Generated by KConfigXT
#include <KLocalizedString>
#include <QLocale>
#include <QDebug>

SyncEngine& SyncEngine::instance()
{
    static SyncEngine inst;
    return inst;
}

SyncEngine::SyncEngine(QObject *parent)
    : QObject(parent), m_client(new MinifluxClient(this)), m_syncTimer(new QTimer(this))
{
    // Load cached values from KConfigXT on startup
    m_apiUrl = Settings::self()->apiUrl();
    m_apiKey = Settings::self()->apiKey();
    m_syncInterval = Settings::self()->syncInterval();
    m_showToolbarLabels = Settings::self()->showToolbarLabels();
    m_cleanSync = Settings::self()->cleanSync();
    m_markAsReadOnOpen = Settings::self()->markAsReadOnOpen();
    m_markAsReadOnScroll = Settings::self()->markAsReadOnScroll();
    m_titleLines = Settings::self()->titleLines();
    m_lastSyncTime = Settings::self()->lastSyncTime();
    emit lastSyncTimeChanged();
    
    qDebug() << "SyncEngine initialized. Loaded Settings:"
             << "\n  API URL:" << m_apiUrl
             << "\n  Sync Interval:" << m_syncInterval
             << "\n  Last Sync Time:" << m_lastSyncTime.toString()
             << "\n  Config File:" << Settings::self()->config()->name();
 
    connect(m_client, &MinifluxClient::categoriesFetched, this, [this](const QList<Category>& categories) {
        DatabaseManager::instance().saveCategories(categories);
        m_client->fetchFeeds(m_apiUrl, m_apiKey);
    });

    connect(m_client, &MinifluxClient::feedsFetched, this, [this](const QList<Feed>& feeds) {
        DatabaseManager::instance().saveFeeds(feeds);
        // After feeds, fetch articles using cached credentials
        m_client->fetchArticles(m_apiUrl, m_apiKey);
    });

    connect(m_client, &MinifluxClient::articlesFetched, this, [this](const QList<Article>& articles) {
        DatabaseManager::instance().saveArticles(articles);
        m_isSyncing = false;
        m_lastSyncTime = QDateTime::currentDateTime();
        Settings::setLastSyncTime(m_lastSyncTime);
        Settings::self()->save();
        emit lastSyncTimeChanged();
        emit syncStatusChanged();
        emit syncFinished(true);
        emit articlesUpdated();
    });

    connect(m_client, &MinifluxClient::articleUpdated, this, [this](const Article& article) {
        qDebug() << "Received article update for ID:" << article.id << "Title:" << article.title;
        DatabaseManager::instance().saveArticles({article});
        emit articlesUpdated();
    });

    connect(m_client, &MinifluxClient::contentFetched, this, [this](long entryId, const QString& content) {
        qDebug() << "Received fetched content for entry ID:" << entryId << "Content length:" << content.length();
        DatabaseManager::instance().updateArticleContent(entryId, content);
        emit articlesUpdated();
    });

    connect(m_client, &MinifluxClient::articleStatusUpdated, this, [this](long entryId, const QString& status) {
        emit articleStatusUpdated(entryId, status);
    });

    connect(m_client, &MinifluxClient::articleBookmarkToggled, this, [this](long entryId) {
        emit articleBookmarkToggled(entryId);
    });

    connect(m_client, &MinifluxClient::errorOccurred, this, [this](const QString& error) {
        qWarning() << "Sync error:" << error;
        m_isSyncing = false;
        emit syncStatusChanged();
        emit syncFinished(false);
    });

    connect(m_syncTimer, &QTimer::timeout, this, &SyncEngine::performSync);
}

QString SyncEngine::apiUrl() const { return m_apiUrl; }
void SyncEngine::setApiUrl(const QString &url)
{
    m_apiUrl = url;
    Settings::setApiUrl(url);
    emit settingsChanged();
}

QString SyncEngine::apiKey() const { return m_apiKey; }
void SyncEngine::setApiKey(const QString &key)
{
    m_apiKey = key;
    Settings::setApiKey(key);
    emit settingsChanged();
}

int SyncEngine::syncInterval() const { return m_syncInterval; }
void SyncEngine::setSyncInterval(int interval)
{
    m_syncInterval = interval;
    Settings::setSyncInterval(interval);
    emit settingsChanged();
}

bool SyncEngine::showToolbarLabels() const { return m_showToolbarLabels; }
void SyncEngine::setShowToolbarLabels(bool show)
{
    if (m_showToolbarLabels == show) return;
    m_showToolbarLabels = show;
    Settings::setShowToolbarLabels(show);
    Settings::self()->save();
    emit showToolbarLabelsChanged();
}

int SyncEngine::titleLines() const
{
    return m_titleLines;
}

void SyncEngine::setTitleLines(int lines)
{
    if (m_titleLines == lines) return;
    m_titleLines = lines;
    Settings::setTitleLines(lines);
    Settings::self()->save();
    emit titleLinesChanged();
}

bool SyncEngine::cleanSync() const { return m_cleanSync; }
void SyncEngine::setCleanSync(bool clean)
{
    m_cleanSync = clean;
    Settings::setCleanSync(clean);
    emit settingsChanged();
}

bool SyncEngine::markAsReadOnOpen() const { return m_markAsReadOnOpen; }
void SyncEngine::setMarkAsReadOnOpen(bool mark)
{
    m_markAsReadOnOpen = mark;
    Settings::setMarkAsReadOnOpen(mark);
    emit settingsChanged();
}

bool SyncEngine::markAsReadOnScroll() const { return m_markAsReadOnScroll; }
void SyncEngine::setMarkAsReadOnScroll(bool mark)
{
    m_markAsReadOnScroll = mark;
    Settings::setMarkAsReadOnScroll(mark);
    emit settingsChanged();
}

void SyncEngine::saveSettings()
{
    Settings::self()->save();
    qDebug() << "Settings saved. URL:" << m_apiUrl << "Key length:" << m_apiKey.length();
}

void SyncEngine::startIntervalSync()
{
    m_syncTimer->start(m_syncInterval * 60 * 1000);
}

void SyncEngine::forceSync()
{
    performSync();
}

void SyncEngine::performSync()
{
    if (m_isSyncing) return;

    if (m_apiUrl.isEmpty() || m_apiKey.isEmpty()) {
        qWarning() << "Miniflux API URL or Key not set, skipping sync.";
        return;
    }

    qDebug() << "Starting sync with URL:" << m_apiUrl << (m_cleanSync ? "[CLEAN SYNC]" : "");
    if (m_cleanSync) {
        DatabaseManager::instance().clearAllData();
    }
    m_isSyncing = true;
    emit syncStatusChanged();
    emit syncStarted();
    m_client->fetchCategories(m_apiUrl, m_apiKey);
}

void SyncEngine::fetchFullContent(long entryId)
{
    if (m_apiUrl.isEmpty() || m_apiKey.isEmpty()) return;
    qDebug() << "Requesting full content for entry ID:" << entryId;
    m_client->fetchArticleContent(m_apiUrl, m_apiKey, entryId);
}

void SyncEngine::updateArticleStatus(long entryId, const QString& status)
{
    if (m_apiUrl.isEmpty() || m_apiKey.isEmpty()) return;
    if (m_cleanSync) {
        qDebug() << "Clean Sync enabled: skipping updateArticleStatus for ID:" << entryId;
        return;
    }
    qDebug() << "Updating article status on server:" << entryId << "to" << status;
    m_client->updateArticleStatus(m_apiUrl, m_apiKey, entryId, status);
}

void SyncEngine::toggleArticleBookmark(long entryId)
{
    if (m_apiUrl.isEmpty() || m_apiKey.isEmpty()) return;
    if (m_cleanSync) {
        qDebug() << "Clean Sync enabled: skipping toggleArticleBookmark for ID:" << entryId;
        return;
    }
    qDebug() << "Toggling article bookmark on server:" << entryId;
    m_client->toggleArticleBookmark(m_apiUrl, m_apiKey, entryId);
}

QString SyncEngine::lastSyncTimeText() const
{
    QString result;
    if (!m_lastSyncTime.isValid() || m_lastSyncTime.isNull()) {
        result = i18n("Never synced");
    } else {
        result = i18n("Last sync: %1", QLocale().toString(m_lastSyncTime.time(), QLocale::ShortFormat));
    }
    qDebug() << "SyncEngine::lastSyncTimeText() returning:" << result;
    return result;
}
